window.LECTURES = [{"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 1, "image": "assets/pages/premalignant_01.jpg", "sourceText": "Premalignant lesion", "heading": "Premalignant Lesions – الصفحة 1", "explanation": "هذه الصفحة جزء من تسلسل المحاضرة. اقرأ النص الأصلي الظاهر بجانب الصورة، ثم اربط المصطلحات بالشرح الموجود في الصفحات السابقة واللاحقة. إذا كانت الصفحة تحتوي صورة فقط، استخدمها كتدريب على التعرف البصري ولا تفترض تفاصيل غير مكتوبة في السلايد.", "imageGuide": "الصورة الأصلية من ملف المحاضرة محفوظة هنا بنفس ترتيبها. كبّرها وراقب شكل النسيج أو الآفة، ثم قارنها بالعلامات المكتوبة في الصفحات المرتبطة بها."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 2, "image": "assets/pages/premalignant_02.jpg", "sourceText": "Premalignant lesion\nA clinically benign, \nhistologically altered \ntissue that has a greater \nrisk of malignant \ntransformation than \nnormal.", "heading": "يعني إيه Premalignant lesion؟", "explanation": "هي منطقة نسيج شكلها الإكلينيكي ممكن يبدو حميدًا، لكن تركيبها تحت الميكروسكوب متغير، ولذلك احتمال تحولها إلى سرطان أعلى من النسيج الطبيعي. كلمة pre معناها قبل، وmalignant معناها خبيث؛ أي حالة قبل السرطان وليست سرطانًا غازيًا بالفعل.", "imageGuide": "تخيّل إن الخلايا في طبقة الظهارة بدأت تتصرف بشكل غير منظم، لكن لسه ما اخترقتش الحد الفاصل بينها وبين النسيج الضام. وجود الخطر لا يعني أن التحول حتمي."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 3, "image": "assets/pages/premalignant_03.jpg", "sourceText": "1.\nEpithelial dysplasia\n2.\nIntact basement membrane\n3.\nNo invasion to underlying C.T.\n4.\nNo metastasis\nPremalignant lesion", "heading": "أربع علامات تميّز Premalignant lesion", "explanation": "1) Epithelial dysplasia: تغير غير طبيعي في ترتيب وشكل خلايا الظهارة. 2) Intact basement membrane: الغشاء القاعدي ما زال سليمًا. 3) No invasion to underlying C.T.: لا توجد خلايا اخترقت إلى Connective Tissue. 4) No metastasis: لا توجد نقائل.", "imageGuide": "الصورة ترسم طبقة الظهارة فوق Basement membrane. الخلايا غير الطبيعية موجودة داخل الظهارة، لكن الخط الفاصل لم ينقطع. لذلك نسميها مرحلة قبل الغزو."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 4, "image": "assets/pages/premalignant_04.jpg", "sourceText": "Epithelial dysplasia\n+\nIntact basement \nmembrane\n=\nPremalignant lesion\nEpithelial dysplasia\n+\nRupture of basement \nmembrane\n=\nInvasive carcinoma\nInvasive cancer\nCarcinoma insitu", "heading": "الفرق الحاسم: Carcinoma in situ مقابل Invasive carcinoma", "explanation": "في Carcinoma in situ تكون الخلايا غير الطبيعية ممتدة داخل الظهارة مع بقاء Basement membrane سليمًا. في Invasive carcinoma يحدث Rupture للغشاء القاعدي وتدخل الخلايا إلى الـ Stroma/Connective tissue؛ وهذا هو الغزو.", "imageGuide": "اقرأ الرسم من أعلى لأسفل: في الجهة الأولى الخلايا الشاذة محصورة فوق الغشاء. في الثانية ترى خلايا نازلة أسفل الغشاء داخل النسيج الضام. احفظ المعادلة: Dysplasia + intact basement membrane = in situ؛ أما dysplasia + rupture = invasive carcinoma."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 5, "image": "assets/pages/premalignant_05.jpg", "sourceText": "➢Types\n*Leukoplakia\n* oral submucous fibrosis\n*Erythroplakia\n* PVL (proliferative verrucous leukoplakia) \n*Actinic chelitis\nPremalignant lesion", "heading": "أنواع Premalignant lesions المذكورة في المحاضرة", "explanation": "المحاضرة تسرد: Leukoplakia، Erythroplakia، Actinic cheilitis، Oral submucous fibrosis، وPVL اختصار Proliferative verrucous leukoplakia. هذه الصفحة تعرض أسماء الأنواع فقط ولا تقدم تفاصيل تشخيصية أو سريرية لكل نوع.", "imageGuide": "احفظ القائمة كما وردت. لا تنسب لأي نوع صفات أو علاجًا من خارج المحاضرة أثناء مذاكرة هذه الصفحة."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 6, "image": "assets/pages/premalignant_06.jpg", "sourceText": "Epithelial dysplasia\n “Epithelial dysplasia” = abnormal and\ndisordered formation of epithelial \ntissue\n “Atypia” = abnormal nuclear features", "heading": "Epithelial dysplasia و Atypia", "explanation": "Epithelial dysplasia معناها تكوّن غير طبيعي وغير منتظم لنسيج الظهارة. أما Atypia فتعني وجود صفات نووية غير طبيعية. الأولى وصف لاضطراب النسيج/نضجه، والثانية تركّز على شكل النواة.", "imageGuide": "اعتبر الظهارة مبنى من طوابق: dysplasia تعني إن ترتيب الطوابق ونضج الخلايا مختل. Atypia تعني إن شكل مكونات الخلايا، خصوصًا النواة، غير طبيعي."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 7, "image": "assets/pages/premalignant_07.jpg", "sourceText": "A. Cytological \n(tissue/ \ncellular) changes\n1) Basal cell hyperplasia.\n2) Drop shaped rete pegs.\n3) Disturbed  polarity  of \nbasal  cells  or  loss  of \ncellular orientation.\n4) Loss  or  reduction  of\nadhesion\nintercellular\n(or cohesion).\n5) Irregular\nstratification\nepithelial\nor\ndisturbed maturation.\nCriteria of epithelial dysplasia\nB. Nuclear changes\n1) Nuclear\nhyperchromatism\n(↑) \nin\n2) Alteration\nN/C ratio.\n3) Increased\nand\nabnormal mitoses.\n4) Dyskaryosis\n5) Piokilokarynosis\n6) Nuclear and cellular\npleomorphism.\n7) Prominent \nand\nenlarged nucleoli\nC.Dyskeratosis.\n1) individual \ncell \nkeratinization\n2) Keratin \nor \nepithelial \npearls", "heading": "خريطة Criteria of epithelial dysplasia", "explanation": "المحاضرة تقسم العلامات إلى ثلاث مجموعات: A) Cytological/tissue changes: خمس علامات تخص ترتيب الخلايا والطبقات. B) Nuclear changes: سبع علامات تخص النواة والانقسام. C) Dyskeratosis: التقرن المبكر لخلايا منفردة أو تكوّن Keratin/Epithelial pearls.", "imageGuide": "ذاكرها كمجموعات لا كقائمة طويلة عشوائية: شكل وترتيب النسيج، ثم النواة والانقسام، ثم التقرن غير الطبيعي. الصفحات التالية تفصل كل علامة."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 8, "image": "assets/pages/premalignant_08.jpg", "sourceText": "لا يوجد نص قابل للاستخراج في هذه الصفحة؛ راجع الصورة الأصلية.", "heading": "صورة مجهرية عامة لـ Epithelial dysplasia", "explanation": "هذه الصفحة صورة نسيجية توضح تغيرات الظهارة في dysplasia. استخدمها لتدريب عينك على ملاحظة ازدحام الخلايا واضطراب ترتيب الطبقات مقارنة بالظهارة الطبيعية؛ تفاصيل كل علامة منفصلة في الصفحات 9–23.", "imageGuide": "الصورة الكبيرة تعرض طبقة الظهارة الوردية/البنفسجية فوق النسيج الضام. يوجد إدراج مكبر لخلية/خلايا لتوضيح التفاصيل الخلوية. لا تعتمد على اللون وحده؛ ركز على ازدحام الخلايا واختلاف الأنوية."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 9, "image": "assets/pages/premalignant_09.jpg", "sourceText": "A- Cytological (cellular) changes (evident at low–power \nmagnification)\n1.Basal cell hyperplasia. \nThe    presence    of \nseveral layers of basal \ncells & appearance of \ncrowded  cells.  It  is \noften  associated  with \ndrop–shaped \nrete \npegs.\nCriteria of epithelial dysplasia", "heading": "Basal cell hyperplasia", "explanation": "Basal layer هي الطبقة القاعدية التي تنشأ منها خلايا الظهارة الجديدة. Hyperplasia تعني زيادة عدد الخلايا. هنا نرى عدة صفوف من الخلايا القاعدية بدل صف منظم، فتبدو الخلايا مزدحمة (crowded). وغالبًا ترتبط بـ Drop-shaped rete pegs.", "imageGuide": "في الصورة النسيجية ابحث عن أسفل الظهارة قرب النسيج الضام: بدل صف قاعدي منتظم ستجد خلايا كثيرة متراصة. لا تخلط بين زيادة عدد الخلايا وبين كبر حجم الخلية."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 10, "image": "assets/pages/premalignant_10.jpg", "sourceText": "• Drop  shaped  rete \npegs→  The  rete \npegs  are  wide  at \ntheir deepest part \nthan   they   are \nmore superficially.", "heading": "Drop-shaped rete pegs", "explanation": "Rete pegs هي امتدادات من الظهارة نازلة باتجاه النسيج الضام. في الشكل الطبيعي تكون الامتدادات أكثر انتظامًا. في dysplasia تصبح عريضة عند الجزء العميق/السفلي مقارنة بالجزء السطحي، فتشبه القطرة المقلوبة.", "imageGuide": "في الصورتين لاحظ الامتدادات الوردية النازلة. ركز على شكل النهاية العميقة: عريضة ومستديرة، بينما الجزء الأقرب للسطح أضيق. هذه هي فكرة drop-shaped."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 11, "image": "assets/pages/premalignant_11.jpg", "sourceText": "3.Disturbed (or loss) \npolarity of basal cells\nThe  basal cells have \nno definite long axis\ndirected \nsurface\nto  \nthe \nso \nnuclei\nhave no polarity due \nto \nloss \nof \nhemidesmosome.", "heading": "Disturbed polarity of basal cells", "explanation": "Polarity معناها اتجاه الخلية. طبيعيًا خلايا الطبقة القاعدية لها محور واتجاه منظم نحو سطح الظهارة. في dysplasia تفقد هذا الاتجاه؛ فتصبح الخلايا وأنويتها غير مصطفة بصورة منتظمة. الشريحة تربط ذلك بفقد Hemidesmosome.", "imageGuide": "تخيّل صف جنود كلهم مواجهين الاتجاه نفسه. فقدان polarity يعني أن كل خلية تتجه بطريقة مختلفة. في الصورة لا تبحث عن لون واحد؛ ابحث عن فقدان الاصطفاف والاتجاه."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 12, "image": "assets/pages/premalignant_12.jpg", "sourceText": "4. Loss or reduction of intercellular desmosomal \njunction → loss of cellular adhesion (or cohesion).", "heading": "Loss of intercellular adhesion / cohesion", "explanation": "Desmosomes هي وصلات تربط الخلايا الظهارية ببعضها. إذا قلت أو فقدت، يقل تماسك الخلايا (cohesion/adhesion) ويصبح ترتيبها أقل انتظامًا.", "imageGuide": "شبهها بمشابك تثبت الطوب ببعضه. عندما تقل المشابك يصبح الجدار أقل تماسكًا. الصورة توضح اضطراب اتصال الخلايا ببعضها."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 13, "image": "assets/pages/premalignant_13.jpg", "sourceText": "5. Irregular \nepithelial \nstratification\nor \ndisturbed \nshow a proper\nmaturation. The cells no longer \nsequence \nof morphological \nand\nmaturational\nchanges as they pass from the basal layer to the \nsurface.", "heading": "Irregular epithelial stratification / disturbed maturation", "explanation": "Stratification هو ترتيب الخلايا في طبقات. طبيعيًا الخلية تبدأ من basal layer ثم تتغير تدريجيًا كلما تحركت نحو السطح (maturation). في dysplasia لا تتبع الخلايا هذا التسلسل الطبيعي في الشكل والنضج.", "imageGuide": "اقرأ الظهارة من القاعدة إلى السطح: الطبيعي انتقال تدريجي. في الصورة الخلايا لا تنضج بالتدرج المتوقع، وتظهر خلايا غير ناضجة في مستويات أعلى."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 14, "image": "assets/pages/premalignant_14.jpg", "sourceText": "B- Nuclear changes (evident at \nhigh–power magnification)", "heading": "Nuclear changes: افحص بتكبير أعلى", "explanation": "هذه بداية مجموعة التغيرات النووية التي تحتاج High-power magnification. المقصود فحص تفاصيل النواة والانقسام: عدد الانقسامات، شكلها، حجم النواة، شدة صبغتها، النويات، واختلاف أحجام الخلايا.", "imageGuide": "الفرق عن Cytological changes أن عينك هنا تركز على تفاصيل كل خلية ونواتها، لا على شكل الطبقات بالكامل."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 15, "image": "assets/pages/premalignant_15.jpg", "sourceText": "Normal \nmitosis", "heading": "Normal mitosis", "explanation": "Mitosis هو انقسام الخلية لإنتاج خليتين بنتين. الرسم يمر بمراحل الانقسام: Prophase، Prometaphase، Metaphase، Anaphase، Telophase. هذه صورة مرجعية للشكل الطبيعي الذي نقارن به الانقسامات الشاذة.", "imageGuide": "الفكرة الامتحانية: الطبيعي له تنظيم ومراحل واضحة. عند dysplasia قد يزيد عدد الانقسامات أو تظهر في أماكن غير معتادة أو بأشكال غير طبيعية."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 16, "image": "assets/pages/premalignant_16.jpg", "sourceText": "B- Nuclear changes (evident at high–power \nmagnification) \nA. Increased in number\nB. Abnormal     location \nwithin  the  epithelium \nand may appear at all \nlevels rather than in its \nusual basal location\nC. Abnormal form/figure \n(tripolar or  star shape \nor    bizarre    shape \nmitoses).\n1) Increased mitoses and abnormal \nmitotic figure.", "heading": "Increased and abnormal mitoses", "explanation": "ثلاثة أوجه: A) Increased number: عدد الانقسامات أكبر. B) Abnormal location: تظهر الانقسامات في مستويات مختلفة من الظهارة بدل اقتصارها على المنطقة القاعدية المعتادة. C) Abnormal form: أشكال شاذة مثل Tripolar أو star-shaped أو bizarre mitoses.", "imageGuide": "في الصورة الأسهم تشير إلى أشكال انقسام غير معتادة. اسأل نفسك: هل العدد زائد؟ هل المكان غير طبيعي؟ هل شكل الانقسام غريب؟ قد تجتمع أكثر من علامة."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 17, "image": "assets/pages/premalignant_17.jpg", "sourceText": "لا يوجد نص قابل للاستخراج في هذه الصفحة؛ راجع الصورة الأصلية.", "heading": "صورة توضيحية لـ Abnormal mitosis", "explanation": "هذه صورة مكبرة مرتبطة بزيادة الانقسامات وأشكالها غير الطبيعية. السهم يشير إلى شكل انقسام غير معتاد داخل النسيج، وهو ما يدعم علامة atypical mitotic figure.", "imageGuide": "ابحث عن خلية يظهر داخلها الكروموسومات متجمعة في شكل غير مألوف بدل الانقسام المنتظم. اربطها بالثلاث نقاط في صفحة 16: العدد، المكان، والشكل."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 18, "image": "assets/pages/premalignant_18.jpg", "sourceText": "atypical mitoses (M), bizarre cells (B)", "heading": "Atypical mitoses و Bizarre cells", "explanation": "التسمية في الشريحة: M تشير إلى atypical mitosis، وB تشير إلى bizarre cells. الخلايا الشاذة قد تكون كبيرة أو غير منتظمة، والانقسام الشاذ لا يسير بالشكل المعتاد.", "imageGuide": "في الصورة المعلّمة لا تحفظ الحروف وحدها؛ اربط M بالانقسام وB بالخلية الغريبة الشكل. هذه صورة تعرّف بصري."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 19, "image": "assets/pages/premalignant_19.jpg", "sourceText": "لا يوجد نص قابل للاستخراج في هذه الصفحة؛ راجع الصورة الأصلية.", "heading": "خلايا شاذة وأشكال نووية غير منتظمة", "explanation": "الصورة تعرض خلايا وأنوية غير منتظمة في الحجم والشكل، وهي مرتبطة بعلامات atypia وpleomorphism المذكورة في المحاضرة.", "imageGuide": "الأسهم تشير إلى خلايا/أنوية ذات مظهر غير منتظم. هذه صورة للتعرف على التباين الشكلي، وليست رسمًا تشريحيًا لطبقات الظهارة."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 20, "image": "assets/pages/premalignant_20.jpg", "sourceText": "2) Alteration (increase) in nuclear/cytoplasmic ratio from \n1:4 to 1:1 (N=nucleus ≈ 1/6--1/4 of cell).\n3) Nuclear hyperchromatism (abnormally excessively \ndark–staining nuclei)", "heading": "N/C ratio و Nuclear hyperchromatism", "explanation": "N/C ratio هي نسبة حجم Nucleus إلى Cytoplasm. المحاضرة تذكر زيادة النسبة من 1:4 إلى 1:1؛ أي أن النواة أصبحت كبيرة نسبيًا مقارنة بالسيتوبلازم. Nuclear hyperchromatism تعني أن النواة تصطبغ بلون أغمق من الطبيعي.", "imageGuide": "تخيّل خلية فيها مساحة سيتوبلازم واسعة ونواة صغيرة. في dysplasia تكبر النواة نسبيًا ويقل نصيب السيتوبلازم، كما تصبح النواة داكنة بشدة عند الصبغ. في الصورة ركز على الأنوية الداكنة والكبيرة."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 21, "image": "assets/pages/premalignant_21.jpg", "sourceText": "4. Prominent and enlarged nucleoli=\nbasophilic  mass  formed  of  DNA  &  RNA, \nnormally  disappear  during  cell  division  & \nreappear in new daughters.", "heading": "Prominent and enlarged nucleoli", "explanation": "Nucleolus هي النوية داخل النواة، وتصفها المحاضرة بأنها كتلة Basophilic مكوّنة من DNA وRNA. طبيعيًا تختفي أثناء انقسام الخلية ثم تظهر في الخلايا البنات. في dysplasia قد تصبح بارزة وكبيرة.", "imageGuide": "في الصورة الأسهم الحمراء تشير إلى النويات البارزة داخل الأنوية. فرّق بين Nucleus (النواة كاملة) وNucleolus (جسم صغير داخل النواة)."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 22, "image": "assets/pages/premalignant_22.jpg", "sourceText": "5.  Nuclear     and     cellular \npleomorphism.  Nuclei  and \ncells are of different size and\nshape. \n(Dyskaryosis \n& \nPiokilokarynosis)\na) Dyskaryosis: nuclear atypism \nincluding giant nuclei\nb) Piokilokarynosis:  division of \nnuclei without division of\nmultinucleated\ncytoplasm→ \ngiant cell\nc) N.B. Pleomorphism= variation in \nsize and shape", "heading": "Nuclear and cellular pleomorphism", "explanation": "Pleomorphism يعني اختلاف الخلايا والأنوية في الحجم والشكل. Dyskaryosis هو atypism نووي، وقد يشمل Giant nuclei. Piokilokarynosis كما تسميها المحاضرة: انقسام الأنوية دون انقسام السيتوبلازم، فينتج Multinucleated giant cell.", "imageGuide": "الصورة تعرض خلايا متفاوتة الشكل والحجم. اربط المصطلحات: pleo = تنوع/اختلاف؛ dyskaryosis = نواة غير طبيعية؛ multinucleated = أكثر من نواة في الخلية."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 23, "image": "assets/pages/premalignant_23.jpg", "sourceText": "• Premature \nkeratinization \n(maturation)  of  epithelial  cells \nthat occurring below the normal \nkeratin layer  within the spinous \ncell layer either:\ncell \nkeratinization\n1. Individual \npremature \nindividual\ncells \nwithin\nkeratinization \nof\nthe\nspinous cell layer\npearls\n2. Keratin or epithelial \nDisturbed  \n maturation\nof\nintraepithelial groups cells.\n(focal, \nround \nconcentrically \nkeratinized cells).\ncollections \nof \nlayer \nof\nDyskeratosis/abnormal keratinization=", "heading": "Dyskeratosis / abnormal keratinization", "explanation": "هو حدوث Keratinization مبكرًا داخل Spinous cell layer أسفل طبقة الكيراتين السطحية الطبيعية. له صورتان: Individual cell keratinization أي خلية منفردة تتقرن مبكرًا، وKeratin/Epithelial pearls أي مجموعات خلايا تتقرن في دوائر متراكزة.", "imageGuide": "الصورة الأولى تمثل تقرن خلية منفردة وسط الطبقات. الصورة الثانية فيها دوائر وردية متراكزة تشبه اللؤلؤ؛ هذه Keratin pearls. لا تخلطها مع التقرن الطبيعي الموجود على السطح."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 24, "image": "assets/pages/premalignant_24.jpg", "sourceText": "Keratin pearls", "heading": "كيف تتعرف على Keratin pearls؟", "explanation": "هي تجمعات دائرية بؤرية من خلايا متقرنة مرتبة في طبقات متحدة المركز (concentrically layered). تظهر كدوائر/بصلات وردية داخل النسيج.", "imageGuide": "في صورة الصفحة ابحث عن الدوائر الوردية المتراكزة. تذكّر شكل حلقات البصلة أو اللؤلؤة. الشريحة تضع الاسم مباشرة: Keratin pearls."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 25, "image": "assets/pages/premalignant_25.jpg", "sourceText": "Degree/Severity of epithelial dysplasia\n“Severity\" or intensity of dysplasia \nare    classified    microscopically \naccording     to     amount     of \ninvolvement of tissue as:\n1. Mild (focal atypia)\n2. Moderate\n3. Severe", "heading": "Severity of epithelial dysplasia", "explanation": "درجة الشدة تصنف حسب مقدار/عمق الظهارة المصاب بالتغيرات: Mild، Moderate، Severe. كلما امتدت التغيرات من الطبقة القاعدية إلى مستويات أعلى زادت الشدة.", "imageGuide": "المعيار الأساسي هنا ليس عدد العلامات فقط، بل إلى أي ارتفاع وصلت التغيرات داخل سمك الظهارة."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 26, "image": "assets/pages/premalignant_26.jpg", "sourceText": "• Mild epithelial dysplasia: alteration limited to basal and \nparabasal layers.\n• Moderate \nepithelial\ndysplasia: \ndemonstrates\ninvolvement from basal layer to mid portion of spinous \nlayer.\n• Severe epithelial dysplasia: alterations from basal layer \nto a level above the midpoint of epithelium.", "heading": "Mild vs Moderate vs Severe", "explanation": "Mild: التغيرات محدودة في Basal وParabasal layers. Moderate: تمتد من Basal layer إلى منتصف Spinous layer. Severe: تمتد من Basal layer إلى مستوى أعلى من منتصف الظهارة.", "imageGuide": "الرسم يقارن مدى صعود الخلايا غير الطبيعية. اقرأ من أسفل لأعلى: تغير محصور قرب القاعدة = mild؛ وصل إلى منتصف الطبقة الشوكية = moderate؛ تجاوز المنتصف = severe."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 27, "image": "assets/pages/premalignant_27.jpg", "sourceText": "Mild epithelial dysplasia\n• Alteration \nto \nbasal\nlimited\nand\nparabasal layers", "heading": "Mild epithelial dysplasia – الصورة", "explanation": "العلامات محصورة في Basal وParabasal layers؛ الطبقات العليا لا يظهر فيها نفس الامتداد. عند قراءة الصورة، ركز على الجزء السفلي من الظهارة.", "imageGuide": "هذه ليست إصابة لكل السمك. علامة التمييز هي أن التغيرات قاعدية/فوق قاعدية فقط."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 28, "image": "assets/pages/premalignant_28.jpg", "sourceText": "Mild epithelial dysplasia", "heading": "Mild dysplasia – صورة نسيجية إضافية", "explanation": "هذه صورة إضافية لدرجة Mild epithelial dysplasia. المعيار الذي يجب أن تراه هو أن التغيرات محصورة قرب قاعدة الظهارة في Basal وParabasal layers.", "imageGuide": "ركز على الجزء السفلي من الظهارة قرب النسيج الضام؛ لا يمتد التغير غير الطبيعي إلى كامل السمك."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 29, "image": "assets/pages/premalignant_29.jpg", "sourceText": "Moderate epithelial dysplasia\n• Involvement from basal layer to mid portion of \nspinous layer", "heading": "Moderate epithelial dysplasia – الصورة", "explanation": "التغيرات تبدأ من Basal layer وتمتد حتى منتصف Spinous layer. لذلك هي أعمق من mild لكنها لا تصل إلى أعلى من منتصف الظهارة.", "imageGuide": "تخيل خطًا في منتصف سمك الظهارة: إذا وصلت التغيرات إلى هذا المستوى تقريبًا فهذه Moderate وفق تعريف المحاضرة."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 30, "image": "assets/pages/premalignant_30.jpg", "sourceText": "Moderate epithelial dysplasia", "heading": "Moderate dysplasia – صورة نسيجية إضافية", "explanation": "الصورة تمثل Moderate epithelial dysplasia؛ أي أن التغيرات تمتد من القاعدة إلى منتصف Spinous layer تقريبًا.", "imageGuide": "قارنها بصورة mild: التغيرات هنا صاعدة إلى مستوى أعلى داخل الظهارة، لكنها لم تصل إلى كل السمك."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 31, "image": "assets/pages/premalignant_31.jpg", "sourceText": "Severe epithelial dysplasia\n• Alterations from basal layer to a level \nabove the midpoint of epithelium", "heading": "Severe epithelial dysplasia – الصورة", "explanation": "التغيرات تمتد من Basal layer إلى مستوى أعلى من منتصف سمك الظهارة، لكنها ليست بالضرورة كل السمك؛ إذا شملت السمك كله ننتقل إلى Carcinoma in situ حسب المحاضرة.", "imageGuide": "انتبه للفرق الدقيق بين severe وin situ: severe يتجاوز المنتصف، أما in situ فيشمل السمك الكامل."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 32, "image": "assets/pages/premalignant_32.jpg", "sourceText": "Severe epithelial dysplasia", "heading": "Severe dysplasia – صورة نسيجية", "explanation": "الصورة توضح امتداد التغيرات إلى مستوى أعلى من منتصف الظهارة. هذه هي نقطة تعريف Severe dysplasia في المحاضرة.", "imageGuide": "تتبع سمك الظهارة من القاعدة للسطح، ولاحظ أن الخلايا غير الطبيعية تشغل أكثر من النصف."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 33, "image": "assets/pages/premalignant_33.jpg", "sourceText": "Severe epithelial dysplasia", "heading": "Severe dysplasia – مثال بصري آخر", "explanation": "مثال إضافي على Severe epithelial dysplasia. استخدمه لتثبيت فكرة أن التغيرات تجاوزت منتصف سمك الظهارة.", "imageGuide": "المطلوب في الامتحان غالبًا تحديد الدرجة من مدى انتشار الخلايا غير الطبيعية رأسيًا."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 34, "image": "assets/pages/premalignant_34.jpg", "sourceText": "carcinoma insitu\n• When    the    entire \nthickness of epithelium \nis involved\n• Carcinoma   insitu   →\ndysplastic epithelial cell\nthat extend from the \nto \nthe\nbasal \nsurface\nlayer\nof \nmucosa\n(“top–to–bottom” \nchange).", "heading": "Carcinoma in situ", "explanation": "في هذه الحالة يشمل التغير dysplastic epithelial cells كامل سمك الظهارة من Basal layer إلى السطح؛ لذلك تصفه المحاضرة بأنه Top-to-bottom change.", "imageGuide": "الصورة تقارن الامتداد الرأسي: لا توجد طبقة ظهارية سليمة تفصل بين الخلايا الشاذة والسطح. ومع ذلك، لا يعني هذا وحده وجود غزو."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 35, "image": "assets/pages/premalignant_35.jpg", "sourceText": "• The important feature \nof carcinoma in situ is \nthat  invasion  has  not \noccurred  because the \nbasement   membrane\nis \nintact\nthus \ncannot\nmetastases, \noccur.", "heading": "لماذا Carcinoma in situ ليس Invasive؟", "explanation": "الصفة الحاسمة أن Basement membrane ما زال intact؛ لم يحدث invasion إلى النسيج الضام. لذلك وفق المحاضرة لا تحدث metastasis في هذه المرحلة.", "imageGuide": "احفظها: كامل سمك الظهارة مصاب، لكن الغشاء القاعدي سليم. كلمة in situ تعني في موضعها؛ لم تخترق الحاجز إلى ما تحته."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 36, "image": "assets/pages/premalignant_36.jpg", "sourceText": "Carcinoma insitu", "heading": "Carcinoma in situ – صورة توضيحية", "explanation": "هذه الصورة مرتبطة بمرحلة Carcinoma in situ: التغيرات تشمل كامل سمك الظهارة، لكن لا يوجد اختراق للـ Basement membrane وفق تعريف المحاضرة.", "imageGuide": "اربط الصورة بالصفحتين 34 و35: full-thickness epithelial involvement مع basement membrane intact."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 37, "image": "assets/pages/premalignant_37.jpg", "sourceText": "لا يوجد نص قابل للاستخراج في هذه الصفحة؛ راجع الصورة الأصلية.", "heading": "صفحة ختامية بلا نص قابل للاستخراج", "explanation": "لا يظهر نص محاضرة قابل للاستخراج في هذه الصفحة. لا توجد معلومة إضافية أضيفها من عندي؛ راجع السلايد كما هو إن كان يحتوي علامة أو صورة في نسختك.", "imageGuide": "صفحة نهاية/فاصل في ملف PDF."}, {"course": "premalignant", "courseTitle": "Premalignant Lesions", "page": 38, "image": "assets/pages/premalignant_38.jpg", "sourceText": "لا يوجد نص قابل للاستخراج في هذه الصفحة؛ راجع الصورة الأصلية.", "heading": "صفحة ختامية بلا نص قابل للاستخراج", "explanation": "لا يظهر نص محاضرة قابل للاستخراج في هذه الصفحة. لا توجد معلومة إضافية أضيفها من عندي؛ راجع السلايد كما هو إن كان يحتوي علامة أو صورة في نسختك.", "imageGuide": "صفحة نهاية/فاصل في ملف PDF."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 1, "image": "assets/pages/benign_01.jpg", "sourceText": "Benign epithelial tissue neoplasms \n1- Squamous cell papilloma\n2- Keratoacanthoma", "heading": "خريطة المحاضرة: Benign epithelial tissue neoplasms", "explanation": "المحاضرة تبدأ بورمين من الظهارة: Squamous cell papilloma وKeratoacanthoma. بعدهما تنتقل إلى Benign connective tissue neoplasms.", "imageGuide": "هذه صفحة تقسيم المنهج: احفظ أن أول جزأين epithelial، ثم يبدأ جزء connective tissue من الصفحة 9."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 2, "image": "assets/pages/benign_02.jpg", "sourceText": "➢Definition\nA benign neoplsm of stratified squamous\nepithelium.\n➢Etiology\nHuman papilloma virus\nType 6,11\n1.Squamous cell \npapilloma", "heading": "Squamous cell papilloma: التعريف والسبب", "explanation": "هو Benign neoplasm ينشأ من Stratified squamous epithelium. وتذكر المحاضرة Human papilloma virus (HPV) types 6 و11 كسبب/ارتباط.", "imageGuide": "Papilloma غالبًا نمو بارز من سطح الظهارة. تذكر أن نوعي HPV المذكورين في السلايد هما 6 و11، ولا تعمم أرقامًا أخرى على هذه المحاضرة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 3, "image": "assets/pages/benign_03.jpg", "sourceText": "➢Clinical picture\nAge: at any age.\nSite: any oral site as Lip, tongue, palate.\nShape: exophytic mass, sessile or pedunculated Forming finger like\nprojections (verrucus or “cauliflowerlike”appearance).\nColor: white, or normal in color depending on the amount of surface\nkertinization.\nConsistency: soft. \nSymptoms: asymptomatic.\n1.Squamous cell \npapilloma", "heading": "Papilloma: الصورة الإكلينيكية", "explanation": "قد يظهر في أي عمر، وفي أي موقع فموي مثل Lip أو Tongue أو Palate. يكون Exophytic mass أي كتلة نامية للخارج، إما Sessile (قاعدة عريضة) أو Pedunculated (متصلة بساق). سطحه Finger-like projections أو شكل Cauliflower. لونه أبيض أو قريب من الطبيعي حسب Surface keratinization، قوامه Soft وغالبًا Asymptomatic.", "imageGuide": "في الصور ابحث عن نتوء مرتفع ذو سطح حليمي/متعرج يشبه القرنبيط. إذا كانت القاعدة عريضة فهو sessile، وإذا اتصل بساق رفيعة فهو pedunculated. اللون الأبيض يرتبط بزيادة التقرن السطحي."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 4, "image": "assets/pages/benign_04.jpg", "sourceText": "➢Histopathology\n•It consists of hyperplastic stratified squamous \nepithelium forming fingers like projections.\n•The epithelium may show hyperkeratosis.\n•The epithelium covers a thin core of connective tissue.\n•The CT shows chronic inflammatory cells.\n•Few koilocytes \n1.Squamous cell \npapilloma", "heading": "Papilloma: Histopathology", "explanation": "توجد Hyperplastic stratified squamous epithelium تصنع Finger-like projections. قد يظهر Hyperkeratosis. كل امتداد يغطي Thin core of connective tissue، وقد يحتوي الـ CT على Chronic inflammatory cells. تذكر الشريحة وجود Few koilocytes.", "imageGuide": "في الصورة الميكروسكوبية تخيل أصابع/زوائد من الظهارة، وكل إصبع له قلب من النسيج الضام. ابحث عن الزوائد المتفرعة والطبقة الظهارية التي تغطيها. Koilocytes مذكورة كخلايا قليلة في السلايد."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 5, "image": "assets/pages/benign_05.jpg", "sourceText": "➢Definition\nIt is a benign neoplasm of stratified squamous \nepithelium that have strong clinical and\nhistopathologic similarity to well –differentiated \nsquamous cell carcinoma.\n2.Keratoacanthoma (self healing carcinoma)", "heading": "Keratoacanthoma: التعريف", "explanation": "تصفه المحاضرة بأنه Benign neoplasm من Stratified squamous epithelium، لكنه يشبه بقوة Well-differentiated squamous cell carcinoma إكلينيكيًا ونسيجيًا. لذلك قد يسبب التباسًا عند التشخيص.", "imageGuide": "اسم Self-healing carcinoma يظهر في عنوان الشريحة، لكنه لا يعني أن تتعامل مع أي آفة مشابهة على أنها بسيطة؛ التشخيص التفريقي يحتاج تقييمًا متخصصًا."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 6, "image": "assets/pages/benign_06.jpg", "sourceText": "➢Etiology\nThe exact etiology is unknown but may be:\n•Human papilloma virus.\n•Sun rays.\n•Genetic factor.\n2.Keratoacanthoma (self healing carcinoma)", "heading": "Keratoacanthoma: Etiology", "explanation": "السبب الدقيق Unknown حسب المحاضرة، والاحتمالات المذكورة: HPV، Sun rays، Genetic factor.", "imageGuide": "لو جاء سؤال exact etiology فالجواب: غير معروف بدقة، وقد يرتبط بالعوامل الثلاثة المذكورة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 7, "image": "assets/pages/benign_07.jpg", "sourceText": "➢Clinical picture\nAge: 50 to 70 years.\nSex: Males more than Females.\nSite: Sun exposed areas as face, hands, lips.\nIt occurs very rarely on oral mucous membrane. \nShape: It is small dome shaped nodule with central \ndepression filled with keratin (keratin plug).\nConsistency: firm.\nIt has a characteristic course:\n•takes 4 to 8 weeks to reach maximum size (1-2 cm in \ndiameter) .\n•Stays 4 to 8 weeks unchanged.\n•Spontaneous regression in 6 to 8 weeks (leaving a \ndepressed scar).\n2.Keratoacanthoma (self healing carcinoma)", "heading": "Keratoacanthoma: Clinical picture", "explanation": "العمر غالبًا 50–70 سنة، والذكور أكثر من الإناث. يظهر غالبًا في المناطق المعرضة للشمس مثل الوجه واليدين والشفاه، ونادر جدًا على Oral mucous membrane. شكله Dome-shaped nodule مع Central depression مليء بالكيراتين (Keratin plug)، وقوامه Firm. مساره: 4–8 أسابيع ليصل 1–2 cm، ثم يثبت 4–8 أسابيع، ثم قد يحدث Spontaneous regression خلال 6–8 أسابيع ويترك Depressed scar.", "imageGuide": "الصورة الإكلينيكية المفتاحية: قبة/عقدة وفي مركزها حفرة أو سدادة كيراتين. احفظ التسلسل الزمني ثلاث مراحل: نمو، ثبات، ثم تراجع تلقائي كما ورد بالأرقام في المحاضرة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 8, "image": "assets/pages/benign_08.jpg", "sourceText": "➢Histopathology\n•Hyperplastic stratified squamous epithelium with a\ncentral crater filled with keratin .\n•The epithelium at the base of the \ncrater\nproliferate\ndownward\nwhich\nStimulate\nchronic\ninflammatory cells In CT.\n•Hyperkeratosis.\n•Deep in the central core of the lesion, there is abnormal\nor premature keratin production like those found in well\ndifferentiated squamous cell carcinoma (individual cell \nkeratinization , keratin pearls).\n2.Keratoacanthoma (self healing carcinoma)", "heading": "Keratoacanthoma: Histopathology", "explanation": "توجد Hyperplastic stratified squamous epithelium حول Central crater ممتلئ بالكيراتين. الظهارة عند قاعدة الحفرة تتكاثر إلى أسفل، مع Chronic inflammatory cells في CT. يوجد Hyperkeratosis، وقد يظهر Individual cell keratinization وKeratin pearls كما في Well-differentiated SCC.", "imageGuide": "في الصورة النسيجية ابحث عن حفرة مركزية تشبه فوهة البركان مليئة بالكيراتين، وحواف ظهارية مرتفعة تحيط بها. هذه الـ crater هي العلامة البصرية الأهم في الشريحة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 9, "image": "assets/pages/benign_09.jpg", "sourceText": "Benign connective tissue neoplasms\n1. Lipoma\n2. Myoma\n3. Neurofibroma\n4. Neurilemoma (Schwannoma)\n5. Granular cell tumor\n6. Congenital epulis of newborn\n7. Chondroma\n8. Osteoma", "heading": "خريطة Benign connective tissue neoplasms", "explanation": "المحاضرة تسرد ثمانية أورام: Lipoma، Myoma، Neurofibroma، Neurilemoma/Schwannoma، Granular cell tumor، Congenital epulis of newborn، Chondroma، Osteoma.", "imageGuide": "قسّمها حسب النسيج: دهني (Lipoma)، عضلي (Myoma)، عصبي (Neurofibroma وSchwannoma، وGranular cell tumor ذي أصل Schwannian حسب الشريحة)، ثم آفة حديثي الولادة، غضروف، وعظم."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 10, "image": "assets/pages/benign_10.jpg", "sourceText": "1. Lipoma\n➢Definition\n•It is a benign neoplasm of fat (adipose tissue).", "heading": "Lipoma: التعريف", "explanation": "ورم حميد من Fat (Adipose tissue)، أي نسيج دهني.", "imageGuide": "اربط الاسم Lipoma بالـ lipid/fat. ستتوقع سريريًا كتلة لينة وقد تبدو صفراء."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 11, "image": "assets/pages/benign_11.jpg", "sourceText": "1. Lipoma\n➢Clinical picture\n•Site: the most common site\nis the the trunk and extremities.\nIntraorally, it may occur on the\ntongue, buccal mucosa, buccal vestibule and floor of the\nmouth.\nShape: soft smooth surfaced mass (nodule). \nColor: Yellowish in color.", "heading": "Lipoma: Clinical picture", "explanation": "أشيع أماكنه عمومًا Trunk وExtremities. داخل الفم قد يظهر على Tongue، Buccal mucosa، Buccal vestibule، وFloor of mouth. شكله Soft smooth-surfaced mass (nodule)، ولونه Yellowish.", "imageGuide": "الصور تعرض كتلة فموية محددة، وقد يظهر اللون الأصفر بسبب طبيعة النسيج الدهني. أهم مفتاحين: soft + yellowish."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 12, "image": "assets/pages/benign_12.jpg", "sourceText": "1. Lipoma\n➢Histopathology\nConnective tissue lesion that is formed of:\n1. Fat cells which are round or polyhedral with clear\ncytoplasm. The nuclei of the\ncells are compressed against one side of the cell\nmembrane.\n2.There is a fibrous connective tissue\ncapsule.\n3.The tumor cells are separated by \nconnective tissue septa\nextending from the capsule (lobulated\nmass).", "heading": "Lipoma: Histopathology", "explanation": "يتكون من Fat cells مستديرة أو متعددة الأضلاع (polyhedral) ذات Cytoplasm صافٍ، وتكون النواة مضغوطة إلى جانب الخلية. يوجد Fibrous connective tissue capsule، وتمتد Septa من الكبسولة لتفصل الخلايا إلى فصوص (Lobulated mass).", "imageGuide": "في الصورة تظهر فراغات كبيرة مستديرة/متعددة الأضلاع تشبه فقاعات؛ النواة مزاحة للطرف. ابحث عن الحواجز الليفية التي تقسم الورم إلى lobules."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 13, "image": "assets/pages/benign_13.jpg", "sourceText": "2. Myoma\n➢Definition\n•It is a benign neoplasm of muscle.\n➢Types\nLeiomyoma: benign neoplasm of smooth \nmuscle.\nRhabdomyoma: benign neoplasm of striated \nmuscle.", "heading": "Myoma: التعريف والأنواع", "explanation": "Myoma هو Benign neoplasm of muscle. نوعان: Leiomyoma من Smooth muscle، وRhabdomyoma من Striated muscle.", "imageGuide": "احفظ جذر الاسم: leio = smooth، rhabdo = striated. التفريق مهم لأن شكل الخلايا المجهري مختلف."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 14, "image": "assets/pages/benign_14.jpg", "sourceText": "2. Myoma\n➢Clinical picture\n•Myomas of the oral cavity are rare.\n•Most common intraoral site is the tongue.\n•Smooth muscle fibers are found intraorally in \nthe wall of blood vessels\nof the tongue.\n•Myomas appear as firm \nmucosal nodule (mass).", "heading": "Myoma: Clinical picture", "explanation": "أورام العضلات داخل الفم نادرة. أكثر موقع داخل الفم هو Tongue. ألياف العضلات الملساء توجد في جدران الأوعية الدموية باللسان. تظهر Myomas كعقدة مخاطية Firm.", "imageGuide": "الصورة تُظهر عقدة على اللسان. لا تستنتج من الموقع وحده نوع العضلة؛ النوع يُحسم بالـ histopathology."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 15, "image": "assets/pages/benign_15.jpg", "sourceText": "2. Myoma\n➢Histopathology \nLeiomyoma:\nConnective tissue lesion that is formed of:\n•Interlacing bundles of spindle shaped \nsmooth muscle cells.\n•The nuclei are elongated and blunt ended.", "heading": "Leiomyoma: Histopathology", "explanation": "يتكون من Interlacing bundles من Smooth muscle cells ذات شكل مغزلي (Spindle-shaped). الأنوية طويلة ونهايتها غير حادة/مستديرة (elongated and blunt-ended).", "imageGuide": "في الصورة ابحث عن حزم وردية متشابكة، وخلايا طويلة رفيعة تشبه المغزل، وأنوية طويلة. كلمة interlacing تعني الحزم متداخلة في اتجاهات مختلفة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 16, "image": "assets/pages/benign_16.jpg", "sourceText": "2. Myoma\n➢Histopathology \nRhabdomyoma:\nConnective tissue lesion that is formed of:\n•Large polygonal cells with granular, eosinophilic \ncytoplasm. with frequent cross striations.\n•Nuclei are small and round \nand located both \nperipherally and centrally.", "heading": "Rhabdomyoma: Histopathology", "explanation": "يتكون من Large polygonal cells، وسيتوبلازم حبيبي Eosinophilic، مع Cross striations متكررة. الأنوية صغيرة ومستديرة وقد توجد طرفيًا أو مركزيًا.", "imageGuide": "العلامة الفارقة في السلايد هي cross striations؛ أي تخطيطات عرضية داخل الخلايا العضلية المخططة. قارنها بخلايا leiomyoma المغزلية ذات الأنوية الطويلة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 17, "image": "assets/pages/benign_17.jpg", "sourceText": "➢Definition\n•It is a benign neoplasm of nerve tissue.\n•It arises from a mixture of cell types including\nSchwann cells and perineural fibroblasts.\n3.Neurofibroma", "heading": "Neurofibroma: التعريف", "explanation": "ورم حميد من Nerve tissue. ينشأ من خليط أنواع خلوية، منها Schwann cells وPerineural fibroblasts.", "imageGuide": "المهم أنه ليس من Schwann cells وحدها؛ المحاضرة تؤكد أنه خليط من أكثر من نوع خلوي."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 18, "image": "assets/pages/benign_18.jpg", "sourceText": "3.Neurofibrom\n➢Clinical picture\n•Neurofibromas can arise as solitary tumors or multiple \nneurofibromas (which is a component of neurofibromatosis \nsyndrome)\n•Site: the most common site is the the skin.\nIntraorally, it may occur on the \ntongue and buccal mucosa.\nShape: soft smooth surfaced \nmass (nodule).", "heading": "Neurofibroma: Clinical picture", "explanation": "قد يظهر كـ Solitary tumor أو Multiple neurofibromas، وقد تكون الأورام المتعددة جزءًا من Neurofibromatosis syndrome. أشيع موقع عمومًا الجلد، وداخل الفم قد يظهر على Tongue وBuccal mucosa. شكله Soft smooth-surfaced nodule.", "imageGuide": "الصورة الفموية تعرض كتلة ملساء. ميّز بين ورم منفرد وبين وجود أورام متعددة كجزء من syndrome."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 19, "image": "assets/pages/benign_19.jpg", "sourceText": "3.Neurofibroma\n➢Clinical picture \nNeurofibromatosis\n(Von Recklinghausen's disease of skin)\n•Patients have multiple neurofibromas that can occur anywhere in\nthe body but are most common on the skin.\n•Another highly characteristic feature is the presence of “cafe\nau lait” pigmentation of\nthe skin\n(smooth-edged, brown macules).\n•These multiple neurofibromas has a great\ntendency for\nmalignant transformation.", "heading": "Neurofibromatosis و Café-au-lait", "explanation": "تذكر المحاضرة Von Recklinghausen's disease of skin: أورام Neurofibromas متعددة قد تظهر في أنحاء الجسم، وأكثرها على الجلد. علامة مميزة أخرى Café-au-lait pigmentation: بقع بنية مسطحة ذات حواف ملساء. وتذكر الشريحة قابلية الأورام المتعددة للتحول الخبيث.", "imageGuide": "الصورة تعرض عقيدات جلدية وبقع بنية. Café-au-lait وصف للون البقعة، مثل لون القهوة بالحليب. هذه علامات سريرية مرتبطة بمتلازمة وليست وصفًا لورم فموي منفرد."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 20, "image": "assets/pages/benign_20.jpg", "sourceText": "3.Neurofibrom\n➢Histopathology\nConnective tissue lesion that is formed of:\n1. Proliferating spindle-shaped cells that have wavy nuclei.\n2. These cells are surrounded with delicate collagen bundles.", "heading": "Neurofibroma: Histopathology", "explanation": "يتكون من Proliferating spindle-shaped cells ذات Wavy nuclei، وتحيط بها Delicate collagen bundles.", "imageGuide": "في الصورة ابحث عن خلايا مغزلية متفرقة وأنوية متموجة/متمططة، مع ألياف كولاجين رقيقة. كلمة wavy nuclei علامة وصفية مهمة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 21, "image": "assets/pages/benign_21.jpg", "sourceText": "4. Neurilemoma (Schwannoma)\n➢Definition\n•It is a benign neoplasm of nerve tissue.\n•It arises from Schwann cell of the nerve sheath.", "heading": "Neurilemoma (Schwannoma): التعريف", "explanation": "ورم حميد من Nerve tissue ينشأ من Schwann cell في Nerve sheath.", "imageGuide": "الفارق الأساسي عن Neurofibroma في هذه المحاضرة: Schwannoma ينشأ من Schwann cells، بينما Neurofibroma خليط خلايا يتضمن Schwann cells وperineural fibroblasts."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 22, "image": "assets/pages/benign_22.jpg", "sourceText": "➢Clinical picture\n•Site: the most common Intraoral site is the tongue.\nShape: it arises as a mass (nodule).\n4. Neurilemoma (Schwannoma)", "heading": "Schwannoma: Clinical picture", "explanation": "أكثر موقع داخل الفم هو Tongue، ويظهر ككتلة أو Nodule.", "imageGuide": "الصورة توضح كتلة على اللسان. المعلومة الإكلينيكية هنا مختصرة؛ التفاصيل التشخيصية النسيجية تأتي في الصفحة التالية."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 23, "image": "assets/pages/benign_23.jpg", "sourceText": "➢Histopathology\nThe tumor has two microscopic types:\nAntoni A and Antoni B.\n1. Antoni A type is characterized by:\nbundles of spindle-shaped Schwann cells.\nThese cells often form a palisaded arrangement around central\nacellular eosinophilic areas known as\nVerocay bodies.\n2. Antoni B the spindle cells are randomly\n(haphazardly) arranged.\n4. Neurilemoma (Schwannoma)", "heading": "Schwannoma: Antoni A وAntoni B", "explanation": "للورم نمطان مجهريان. Antoni A: حزم من spindle-shaped Schwann cells تصطف في نمط Palisading حول مناطق مركزية خالية من الخلايا وEosinophilic تسمى Verocay bodies. Antoni B: الخلايا المغزلية مرتبة عشوائيًا (haphazardly).", "imageGuide": "الصورة الأولى عادة تُظهر صفوفًا متوازية ومنتظمة من الأنوية كأنها سياج (palisade)، وبينها Verocay bodies. الصورة الثانية أقل انتظامًا وعشوائية؛ هذه Antoni B."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 24, "image": "assets/pages/benign_24.jpg", "sourceText": "➢Definition\n•It is a benign neoplasm formed of granular cells.\n•It was believed to be of striated muscle origin.\n•However, recent investigations revealed a nerve tissue\norigin (derived from Schwann cells)\nThe granular cells of the tumors \nare positive to S-100 protein \nthat is present in nerve cells.\n5. Granular cell tumor", "heading": "Granular cell tumor: التعريف والأصل", "explanation": "ورم حميد مكوّن من Granular cells. كان يُعتقد قديمًا أن أصله Striated muscle، لكن المحاضرة تذكر أن الدراسات الأحدث تشير إلى أصل عصبي من Schwann cells. الخلايا إيجابية لـ S-100 protein الموجود في الخلايا العصبية.", "imageGuide": "احفظ التطور في الفهم: اعتقاد قديم عضلي، لكن المصدر المذكور حاليًا في السلايد عصبي/Schwann. S-100 علامة تدعم هذا الأصل."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 25, "image": "assets/pages/benign_25.jpg", "sourceText": "5. Granular cell tumor\n➢Clinical picture\n•Site: the most common Intraoral site is the tongue.\nShape: it arises as a mass (nodule).", "heading": "Granular cell tumor: Clinical picture", "explanation": "أشيع موقع داخل الفم هو Tongue، ويظهر ككتلة أو Nodule.", "imageGuide": "الصفحة تركز على الموقع والشكل. اربط Granular cell tumor باللسان، ثم انتقل للصفات المجهرية في الصفحة التالية."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 26, "image": "assets/pages/benign_26.jpg", "sourceText": "5. Granular cell tumor\n➢Histopathology\nConnective tissue lesion that is formed of:\n•Sheets or nests of large polygonal cells with eosinophilic, granular\ncytoplasm and small centrally or peripherally placed nucleus.\n•The overlying epithelium is hyperplastic and\nmay results in a mistaken diagnosis of squamous\ncell carcinoma (pseudoepitheliomatous \n“pseudocarcinomatous” hyperplasia).", "heading": "Granular cell tumor: Histopathology", "explanation": "يتكون من Sheets أو Nests من خلايا كبيرة متعددة الأضلاع، ذات Eosinophilic granular cytoplasm، ونواة صغيرة قد تكون مركزية أو طرفية. الظهارة المغطية تكون Hyperplastic وقد تشبه Squamous cell carcinoma؛ وهذا يسمى Pseudoepitheliomatous أو Pseudocarcinomatous hyperplasia.", "imageGuide": "الصورة النسيجية قد تخدعك لأن الظهارة السطحية متضخمة ونازلة؛ لا تساوِ ذلك تلقائيًا بسرطان. المحاضرة تسمي هذا المظهر pseudoepitheliomatous hyperplasia."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 27, "image": "assets/pages/benign_27.jpg", "sourceText": "5. Granular cell tumor\n➢Histopathology", "heading": "Granular cell tumor – صورة نسيجية", "explanation": "هذه صفحة صور نسيجية إضافية للـ Granular cell tumor. اربطها بوصف الصفحة 26: sheets/nests من خلايا كبيرة polygonal ذات granular eosinophilic cytoplasm، مع احتمال تضخم الظهارة المغطية.", "imageGuide": "عند فحص الصورة ابحث عن تجمعات الخلايا الحبيبية أسفل الظهارة، وتذكر أن فرط تنسج الظهارة قد يحاكي SCC."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 28, "image": "assets/pages/benign_28.jpg", "sourceText": "6. Congenital epulis of newborn\n➢Definition\n•A congenital tumor that occurs almost exclusively on the \nalveolar ridges of newborns.\n•The histogenesis (origin) of this tumor is unknown.\n•The tumor cells are microscopically identical to those of \ngranular cell tumors but:\n•The cells of the tumor are \nnegative for S-100 protein \n(nerve marker) and actin \n(muscle marker).", "heading": "Congenital epulis of newborn: التعريف", "explanation": "ورم خلقي يحدث تقريبًا حصريًا على Alveolar ridges عند حديثي الولادة. Histogenesis (الأصل النسيجي) غير معروف. خلاياه تشبه خلايا Granular cell tumor مجهريًا، لكن تكون Negative for S-100 وActin.", "imageGuide": "الفرق المناعي مهم: Granular cell tumor إيجابي لـ S-100 حسب السلايد، بينما Congenital epulis سلبي لـ S-100 وActin."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 29, "image": "assets/pages/benign_29.jpg", "sourceText": "➢Clinical picture\n•Appears as a pink-to-red smooth-surfaced mass on the \nalveolar ridge of a newborn.\n•It occurs lateral to the midline and is more common on \nthe maxillary ridge.\n•It affects female more \nthan males.\n•After birth, the tumor\nappears to stop growing and may even diminish in size.\n6. Congenital epulis of newborn", "heading": "Congenital epulis: Clinical picture", "explanation": "كتلة Pink-to-red ذات سطح أملس على Alveolar ridge لمولود حديث. تظهر جانبيًا بعيدًا عن Midline، وأكثر على Maxillary ridge، وتصيب الإناث أكثر من الذكور. بعد الولادة يتوقف نموها غالبًا وقد يقل حجمها.", "imageGuide": "الصورة السريرية المفتاحية هي كتلة على حافة اللثة عند مولود حديث، غالبًا في الفك العلوي وبجانب الخط الأوسط."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 30, "image": "assets/pages/benign_30.jpg", "sourceText": "6. Congenital epulis of newborn\n➢Histopathology Connective tissue lesion\nthat is formed of:\n1. Sheets or nests of large rounded cells with\neosinophilic, granular cytoplasm.\n2. The overlying epithelium never shows\npseudoepitheliomatous hyperplasia but have\natrophy of the rete ridges.", "heading": "Congenital epulis: Histopathology", "explanation": "تتكون من Sheets أو Nests من خلايا كبيرة مستديرة ذات Eosinophilic granular cytoplasm. الظهارة المغطية لا تُظهر Pseudoepitheliomatous hyperplasia، بل يحدث Atrophy of rete ridges.", "imageGuide": "قارنها بـ Granular cell tumor: الخلايا الحبيبية متشابهة، لكن هنا الظهارة لا تُظهر فرط تنسج كاذبًا؛ بل ضمورًا في rete ridges."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 31, "image": "assets/pages/benign_31.jpg", "sourceText": "➢Definition\n•It is a benign neoplasm composed of cartilage.\n•Chondroma is one of the common bone tumors.\n•Gnathic chondromas arise from remnant of cartilaginous \nrests.\n•Such rests are located in the anterior maxilla (in the\nregion of premaxilla), symphysis, coronoid process and \ncondyle.\n7. Chondroma", "heading": "Chondroma: التعريف ومصدر الفك", "explanation": "ورم حميد مكوّن من Cartilage. تذكر المحاضرة أنه من أورام العظام الشائعة، وأن Gnathic chondromas تنشأ من بقايا غضروفية (cartilaginous rests) في مناطق: Anterior maxilla/premaxilla، Symphysis، Coronoid process، وCondyle.", "imageGuide": "Gnathic يعني متعلقًا بالفكين. احفظ أماكن البقايا الغضروفية كما وردت في السلايد؛ ستتكرر في سؤال المواقع."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 32, "image": "assets/pages/benign_32.jpg", "sourceText": "➢Clinical picture\n•Site: Gnathic examples have been found in the condyle, \ncoronoid process, symphysis area or anterior maxilla.\n•Age: It affects adult patients.\n•Consistency: It appears as slowly growing hard swelling.\n•Complication: The lesion may \ncause loosening of the teeth due \nto root resorption.\n7. Chondroma", "heading": "Chondroma: Clinical picture", "explanation": "في الفكين قد يوجد في Condyle أو Coronoid process أو Symphysis أو Anterior maxilla. يصيب البالغين، ويظهر كتورم صلب بطيء النمو. قد يسبب loosening of teeth بسبب Root resorption.", "imageGuide": "الصورة الإكلينيكية الأساسية: hard swelling + slow growth. المضاعفة المذكورة: تخلخل الأسنان بسبب امتصاص الجذور."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 33, "image": "assets/pages/benign_33.jpg", "sourceText": "➢Radiographic features\nIt appears as radiolucency with central areas of \nradiopacity.\n7. Chondroma", "heading": "Chondroma: Radiographic features", "explanation": "يظهر كـ Radiolucency مع مناطق مركزية من Radiopacity.", "imageGuide": "Radiolucent تعني منطقة أغمق/أقل كثافة شعاعيًا، وRadiopaque تعني منطقة أكثر كثافة/أفتح. الصورة تجمع مظهرًا شفافًا شعاعيًا مع بؤر معتمة في المركز."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 34, "image": "assets/pages/benign_34.jpg", "sourceText": "➢Histopathology\nChondroma appears a s a well circumscribed mass of \nhyaline cartilage (homogenous, clear, basophilic material) \nthat shows lacunae containing small chondrocytes with \npale cytoplasm and small round nuclei.\n7. Chondroma", "heading": "Chondroma: Histopathology", "explanation": "كتلة Well-circumscribed من Hyaline cartilage؛ مادة متجانسة شفافة/قاعدية الصبغ (basophilic). تحتوي Lacunae بها Chondrocytes صغيرة ذات Cytoplasm شاحب وأنوية صغيرة مستديرة.", "imageGuide": "Lacunae هي فجوات/مساحات صغيرة داخل الغضروف تسكنها الخلايا الغضروفية Chondrocytes. في الشريحة ابحث عن خلايا داخل فراغات واضحة ضمن مادة غضروفية متجانسة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 35, "image": "assets/pages/benign_35.jpg", "sourceText": "8. Osteoma\n➢Definition\n•It is a benign neoplasm of bone.\n•Tumors composed of mature compact\nor cancellous bone.\n•It may be solitary or multiple (as in case of\nGardner syndrome).", "heading": "Osteoma: التعريف", "explanation": "ورم حميد من العظم، مكوّن من Mature compact أو cancellous bone. قد يكون Solitary أو Multiple كما في Gardner syndrome.", "imageGuide": "Compact يعني عظم كثيف، وCancellous يعني عظم إسفنجي/ترابقي. تعدد الأورام قد يرتبط بـ Gardner syndrome كما تذكر المحاضرة."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 36, "image": "assets/pages/benign_36.jpg", "sourceText": "8. Osteoma\n➢Clinical picture\nOsteomas of the jaws may:\n1.Arise on the surface of the bone, (periosteal osteoma), \nAnd appear as slowly growing hard mass.\nor\n2. May be located in the medullary bone (endosteal \nosteoma).\nSmall endosteal osteomas are asymptomatic, but large \nlesions cause a slowly progressive enlargement of the \naffected area.", "heading": "Osteoma: Clinical picture", "explanation": "قد ينشأ على سطح العظم ويسمى Periosteal osteoma ويظهر ككتلة صلبة بطيئة النمو، أو داخل Medullary bone ويسمى Endosteal osteoma. الأورام الداخلية الصغيرة غالبًا Asymptomatic، أما الكبيرة فتسبب تضخمًا تدريجيًا بطيئًا للمنطقة.", "imageGuide": "فرّق بالمكان: periosteal على السطح، endosteal داخل العظم. الأعراض تتأثر بالحجم؛ الصغير الداخلي قد لا يسبب أعراضًا."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 37, "image": "assets/pages/benign_37.jpg", "sourceText": "8. Osteoma\n➢Radiographic features\nIt appears as a well circumscribed radiopaque mass.", "heading": "Osteoma: Radiographic features", "explanation": "يظهر كـ Well-circumscribed radiopaque mass؛ أي كتلة كثيفة شعاعيًا وحدودها واضحة.", "imageGuide": "مفتاح الأشعة: Radiopaque وليس radiolucent. قارنها مع Chondroma في الصفحة 33."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 38, "image": "assets/pages/benign_38.jpg", "sourceText": "8. Osteoma\n➢Histopathology\n•Compact osteomas are composed of dense\nbone showing minimal marrow tissue.\n•Cancellous osteomas are composed of trabeculae\nof bone\nand marrow tissue.", "heading": "Osteoma: Histopathology", "explanation": "Compact osteoma يتكون من Dense bone مع كمية قليلة جدًا من Marrow tissue. Cancellous osteoma يتكون من Trabeculae of bone وبينها Marrow tissue.", "imageGuide": "في compact ترى عظمًا كثيفًا متراصًا ونخاعًا قليلًا. في cancellous ترى ترابيق عظمية ومساحات نخاعية."}, {"course": "benign", "courseTitle": "Benign Tumors", "page": 39, "image": "assets/pages/benign_39.jpg", "sourceText": "Hamartomas\n➢Harartoma:\nIt is a developmental tumor like malformation characterized by \npresence of normal tissue in normal site, but in excessive \namount.\n➢Nevus: it is a hamartoma occurs on the skin or the mucous \nmembrane.\n➢Types of Nevi:\nKeratotic Nevus: White sponge nevus. \nPigmented or melanocytic nevus.\nVascular Nevi: Hemangioma and lymphangioma.", "heading": "Hamartoma و Nevus", "explanation": "Hamartoma هو تشوه/نمو شبيه بالورم ناتج عن وجود أنسجة طبيعية في مكانها الطبيعي لكن بكمية زائدة. Nevus هو Hamartoma يظهر في الجلد أو الغشاء المخاطي. الأنواع المذكورة: Keratotic nevus مثل White sponge nevus، Pigmented/melanocytic nevus، وVascular nevi مثل Hemangioma وLymphangioma.", "imageGuide": "الفكرة الفارقة: النسيج نفسه طبيعي وموجود في مكانه الطبيعي، لكن كميته زائدة. احفظ تصنيف الـ nevi الثلاثة كما في السلايد."}];
